#include <iostream>
#include <type_traits>
template <typename T, size_t N>
constexpr size_t array_size(const T (&)[N]) { return N; }

template <typename T, size_t Size>
class StaticArray {
public:
  constexpr StaticArray(const T(&data)[Size]) {
    for (size_t i = 0; i < Size; ++i) {
      arr[i] = data[i];
    }
  }
  constexpr T get(size_t index) const { return arr[index]; }
private:
  T arr[Size];
};

int main() {
  constexpr int data[] = {1, 2, 3, 4, 5};
  constexpr StaticArray<int, array_size(data)> myArray(data);
  std::cout << myArray.get(2) << std::endl; // Output: 3
  static_assert(array_size(data) == 5, "Array size check failed");
  return 0;
}
